from collections import deque
from more_itertools import more


def last(iterable: list | tuple | str, default: object | None = None) -> object | None:
    """Return the last item of *iterable*, or *default* if *iterable* is empty.

    iterable: An iterable (e.g., list, tuple, string) from which the last item is to be retrieved.
    default: The value to return if the iterable is empty. If not provided, a ValueError is raised.

    Example:
        >>> last([0, 1, 2, 3])
        3
    """
    try:
        if getattr(iterable, '__reversed__', None):
            return next(reversed(iterable))
        return deque(iterable, maxlen=1)[-1]
    except (IndexError, StopIteration):
        return default

from typing import Iterable, List, Optional, Any, Callable

def strictly_n(iterable: Iterable, n: int, too_short: Optional[Callable[[int], Any]] = None, too_long: Optional[Callable[[int], Any]] = None) -> List:
    """
    Validate that *iterable* has exactly *n* items and return them if it does.

    Parameters:
    - iterable (array): The iterable to validate for having exactly n items.
    - n (integer): The exact number of items the iterable must have.
    - too_short (object, optional): A function to call if the iterable has fewer than n items. It will be called with the actual number of items.
    - too_long (object, optional): A function to call if the iterable has more than n items. It will be called with the number n + 1.

    Example:
    >>> strictly_n(['a', 'b', 'c', 'd'], 4)
    ['a', 'b', 'c', 'd']
    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")

    it = iter(iterable)
    result = []

    for _ in range(n):
        try:
            result.append(next(it))
        except StopIteration:
            if too_short is None:
                raise ValueError(f"Too few items in iterable (got {len(result)})")
            else:
                too_short(len(result))
                return []

    for _ in it:
        if too_long is None:
            raise ValueError(f"Too many items in iterable (got at least {n + 1})")
        else:
            too_long(n + 1)
            return result

    return result

from typing import Iterable, List, Any, cast, Callable

def split_after(iterable: Iterable[Any], pred: str, maxsplit: int = -1) -> list:
    """Yield lists of items from *iterable*, where each list ends with an item where callable *pred* returns True.

    Parameters:
        iterable (array): An iterable to split into sublists.
        pred (object): A callable predicate function that returns True for items where the split should occur.
        maxsplit (integer, optional): Maximum number of splits to perform. If -1, there is no limit.

    Example:
        >>> list(split_after('one1two2', 'lambda s: s.isdigit()'))
        [['o', 'n', 'e', '1'], ['t', 'w', 'o', '2']]
    """
    if not isinstance(pred, str):
        raise ValueError("pred must be a string representation of a function")

    if maxsplit < -1:
        raise ValueError("maxsplit must be -1 or a non-negative integer")

    # Safely parse pred string to a function (example assumes safe input)
    try:
        # Use lambda to wrap the string expression
        pred_func = eval(f"lambda item: {pred}")
    except Exception as e:
        raise ValueError(f"pred is not a valid function: {e}")

    if not callable(pred_func):
        raise ValueError("pred must evaluate to a callable function")

    if maxsplit == 0:
        return [list(iterable)]

    buf = []
    it = iter(iterable)
    splits = 0

    for item in it:
        buf.append(item)
        if pred_func(item) and buf:
            yield buf
            buf = []
            splits += 1
            if maxsplit > 0 and splits >= maxsplit:
                # Append the rest of the iterable as a single list
                remaining = list(it)
                if remaining:
                    yield remaining
                return

    if buf:
        yield buf

    return list(cast(Iterable[List[Any]], split_after(iterable, pred, maxsplit)))

