from itertools import chain, islice, zip_longest
from typing import Any, List, Optional, Tuple, Union


def zip_offset(
    iterables: List[List[Any]],
    offsets: List[int],
    longest: bool = False,
    fill_value: Optional[Any] = None
) -> List[Tuple[Any, ...]]:
    """
    Zip the input *iterables* together, but offset the `i`-th iterable by the `i`-th item in *offsets*.

    Parameters:
    - iterables (List[List[Any]]): A list of iterables to be zipped together with offsets applied.
    - offsets (List[int]): A list of integers representing the offset for each corresponding iterable.
    - longest (bool, optional): If true, continue zipping until the longest iterable is exhausted. Otherwise, stop at the shortest.
    - fill_value (Any, optional): The value to use for missing elements when the longest iterable is enabled.

    Example:
    zip_offset([['0', '1', '2', '3'], ['a', 'b', 'c', 'd', 'e', 'f']], [0, 1]) -> [('0', 'b'), ('1', 'c'), ('2', 'd'), ('3', 'e')]
    """
    if len(iterables) != len(offsets):
        raise ValueError("Number of iterables and offsets didn't match")

    staggered = []
    for it, n in zip(iterables, offsets):
        if n < 0:
            staggered.append(list(chain([fill_value] * -n, it)))
        elif n > 0:
            staggered.append(list(islice(it, n, None)))
        else:
            staggered.append(it)

    if longest:
        return list(zip_longest(*staggered, fillvalue=fill_value))

    return list(zip(*staggered))

from typing import Iterable, Tuple, List, Any

def mark_ends(iterable: Iterable[Any]) -> List[Tuple[bool, bool, Any]]:
    """Yield 3-tuples of the form (is_first, is_last, item). iterable: an iterable collection of items to be processed."""
    try:
        it = iter(iterable)
        first = True
        result = []
        prev = None
        for item in it:
            if prev is not None:
                result.append((False, False, prev))
            prev = item
            first = False
        if prev is not None:
            result.append((True, False, prev))
        # Fix the first and last flags
        if result:
            result[0] = (True, False, result[0][2])
            result[-1] = (False, True, result[-1][2])
        return result
    except Exception as e:
        raise ValueError(f"Invalid input for mark_ends: {e}") from e

from collections.abc import Iterable
from more_itertools import windowed


def locate(iterable: Iterable, pred: object = bool, window_size: int | None = None) -> list[int]:
    """Yield the index of each item in *iterable* for which *pred* returns True.

    *iterable*: An iterable to search for items that satisfy the predicate.
    *pred*: A function that returns True for items to be located. Defaults to bool.
    *window_size*: If provided, the predicate is applied to a sliding window of this size. Defaults to None.

    Example:
        >>> locate([0, 1, 1, 0, 1, 0, 0])
        [1, 2, 4]
    """
    if not isinstance(iterable, Iterable):
        raise ValueError("iterable must be an iterable")
    if pred is not None and not callable(pred):
        raise ValueError("pred must be a callable function")
    if window_size is not None and not isinstance(window_size, int):
        raise ValueError("window_size must be an integer or None")

    result = []
    if window_size is None:
        for i, item in enumerate(iterable):
            if pred is None or pred(item):
                result.append(i)
    else:
        if window_size < 1:
            raise ValueError("window size must be at least 1")
        for i, window in enumerate(windowed(iterable, window_size, fillvalue=None)):
            if pred is None or pred(*[x for x in window if x is not None]):
                result.append(i)
    return result

