def longest_common_prefix(iterables: List[Iterable[Any]]) -> List[Any]:
    """Yield elements of the longest common prefix among given *iterables*.

    iterables: a list of iterables (e.g., strings, lists) to find the longest common prefix among.
    Returns: a list of elements in the longest common prefix.

    >>> longest_common_prefix(['abcd', 'abc', 'abf'])
    ['a', 'b']

    """
    if not iterables:
        return []
    if any(not isinstance(i, Iterable) for i in iterables):
        raise ValueError("All elements of 'iterables' must be iterable.")
    return list(takewhile(lambda x: all_equal(x), zip(*iterables)))

