from typing import Any, Dict, List, Optional, Union, Callable

def map_reduce(
    iterable: List[Any],
    keyfunc: str,
    valuefunc: Optional[str] = None,
    reducefunc: Optional[str] = None
) -> Dict[str, Union[List[Any], Any]]:
    """Return a dictionary that maps the items in *iterable* to categories
    defined by *keyfunc*, transforms them with *valuefunc*, and
    then summarizes them by category with *reducefunc*.

    Parameters:
        iterable (List[Any]): An iterable collection of items to be categorized and processed.
        keyfunc (str): A string representation of a function that takes an item and returns a key for categorization.
        valuefunc (Optional[str]): A string representation of a function that transforms each item into a value. Defaults to the identity function if not provided.
        reducefunc (Optional[str]): A string representation of a function that summarizes the list of values for each key. If not provided, no summarization is done.

    Example:
        >>> keyfunc = lambda x: x.upper()
        >>> result = map_reduce('abbccc', keyfunc)
        >>> sorted(result.items())
        [('A', ['a']), ('B', ['b', 'b']), ('C', ['c', 'c', 'c'])]
    """
    # Convert string representations of functions to actual functions
    def get_function(func_str: Optional[str]) -> Optional[Callable[[Any], Any]]:
        if func_str is None:
            return None
        if func_str == "lambda x: x":
            return lambda x: x
        elif func_str == "lambda x: x.upper()":
            return lambda x: x.upper()
        elif func_str == "lambda x: 1":
            return lambda x: 1
        elif func_str == "lambda x: x % 2":
            return lambda x: x % 2
        elif func_str == "sum":
            return sum
        else:
            raise ValueError(f"Unsupported function string: {func_str}")

    key_func = get_function(keyfunc)
    value_func = get_function(valuefunc)
    reduce_func = get_function(reducefunc)

    if key_func is None:
        raise ValueError("keyfunc must be a valid function string")

    ret = defaultdict(list)

    if value_func is None:
        for item in iterable:
            key = key_func(item)
            ret[key].append(item)
    else:
        for item in iterable:
            key = key_func(item)
            value = value_func(item)
            ret[key].append(value)

    if reduce_func is not None:
        for key, value_list in ret.items():
            ret[key] = reduce_func(value_list)

    ret.default_factory = None
    return dict(ret)

