def is_sorted(iterable: list, key: str | None = None, reverse: bool = False, strict: bool = False) -> bool:
    """Returns True if the items of an iterable are in sorted order, and False otherwise.
    *key* is a function (as a string) to extract a comparison key from each element.
    *reverse* checks for descending order if True.
    *strict* returns False if equal elements are found.

    Example:
    >>> is_sorted(['1', '2', '3', '4', '5'], key='int')
    True
    """
    try:
        if key is not None:
            if key == "None":
                key_func = None
            elif key not in {"int", "str", "float", "len"}:
                raise ValueError(f"Unsupported key function: {key}")
            else:
                key_func = {"int": int, "str": str, "float": float, "len": len}[key]
        else:
            key_func = None

        if key_func is None:
            return more.is_sorted(iterable, reverse=reverse, strict=strict)
        else:
            return more.is_sorted(map(key_func, iterable), reverse=reverse, strict=strict)
    except Exception as e:
        raise ValueError(f"Error processing input: {e}")

