from typing import Dict, Any


def join_mappings(field_to_map: Dict[str, Dict[str, Any]]) -> Dict[str, Dict[str, Any]]:
    """
    Joins multiple mappings together using their common keys.

    Parameters:
    - field_to_map: A dictionary where keys are field names and values are mappings (dictionaries) to be joined.

    Example:
    >>> user_scores = {'elliot': 50, 'claris': 60}
    >>> user_times = {'elliot': 30, 'claris': 40}
    >>> join_mappings({'score': user_scores, 'time': user_times})
    {'elliot': {'score': 50, 'time': 30}, 'claris': {'score': 60, 'time': 40}}
    """
    if not field_to_map:
        raise ValueError("At least one mapping must be provided.")

    ret = defaultdict(dict)

    for field_name, mapping in field_to_map.items():
        if not isinstance(mapping, dict):
            raise ValueError(f"Value for field '{field_name}' must be a dictionary.")
        for key, value in mapping.items():
            ret[key][field_name] = value

    return dict(ret)

