def tail(n: int, iterable: List[T]) -> List[T]:
    """Return an iterator over the last *n* items of *iterable*.

    n: The number of last items to return from the iterable
    iterable: The iterable from which to extract the last n items
    Example: tail(3, 'ABCDEFG') -> ['E', 'F', 'G']

    """
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    if not isinstance(iterable, (list, tuple, str)):
        raise ValueError("iterable must be a list, tuple, or string")

    try:
        size = len(iterable)
    except TypeError:
        return list(deque(iterable, maxlen=n))
    else:
        return list(islice(iterable, max(0, size - n), None))

