from typing import Any, Iterable, List, Tuple


def grouper(
    iterable: Iterable[Any], 
    n: int, 
    incomplete: str = 'fill', 
    fill_value: Any = None
) -> List[Tuple[Any, ...]]:
    """
    Group elements from *iterable* into fixed-length groups of length *n*.

    Parameters:
    - iterable: An iterable to be grouped into fixed-length chunks.
    - n: The size of each group.
    - incomplete: How to handle incomplete groups. Options are 'fill', 'ignore', or 'strict'.
    - fill_value: The value to use for filling incomplete groups when 'incomplete' is 'fill'.

    Example:
    >>> list(grouper('ABCDEF', 3))
    [('A', 'B', 'C'), ('D', 'E', 'F')]
    """
    if n <= 0:
        return []

    if incomplete not in ['fill', 'ignore', 'strict']:
        raise ValueError("Parameter 'incomplete' must be one of 'fill', 'ignore', or 'strict'.")

    iterators = [iter(iterable)] * n
    if incomplete == 'fill':
        return list(zip_longest(*iterators, fillvalue=fill_value))
    elif incomplete == 'strict':
        try:
            return list(zip(*iterators, strict=True))
        except ValueError as e:
            raise ValueError("Incomplete group found and 'strict' mode is enabled.") from e
    else:  # incomplete == 'ignore'
        return list(zip(*iterators))

