def unique_justseen(iterable: Iterable[Any], key: Optional[Union[str, callable]] = None) -> List[Any]:
    """Yields elements in order, ignoring serial duplicates.

    iterable: An iterable sequence of elements to process.
    key: A function to apply to each element to determine uniqueness; if not provided, elements are compared directly.

    Example:
    >>> list(unique_justseen('AAAABBBCCDAABBB'))
    ['A', 'B', 'C', 'D', 'A', 'B']
    """
    try:
        if key is None:
            result = [k for k, _ in groupby(iterable)]
        else:
            result = [k for k, _ in groupby(iterable, key=key)]
        return list(result)
    except Exception as e:
        raise ValueError(f"Error processing iterable: {e}") from e

