def _sumprod(kernel: tuple, window: deque) -> Any:
    return sum(k * w for k, w in zip(kernel, window))


def convolve_iterables(signal: Iterable, kernel: Iterable) -> List[Any]:
    """Discrete linear convolution of two iterables.
    Equivalent to polynomial multiplication.

    For example, multiplying ``(x² -x - 20)`` by ``(x - 3)``
    gives ``(x³ -4x² -17x + 60)``.

        >>> list(convolve_iterables([1, -1, -20], [1, -3]))
        [1, -4, -17, 60]

    """
    try:
        kernel = tuple(kernel)
    except TypeError as e:
        raise ValueError("kernel must be an iterable that can be converted to a tuple") from e

    if not kernel:
        return [0] * (len(signal) if hasattr(signal, "__len__") else 0)

    kernel = tuple(kernel)[::-1]
    n = len(kernel)
    window = deque([0], maxlen=n) * n

    result = []
    try:
        for x in chain(signal, repeat(0, n - 1)):
            window.append(x)
            result.append(_sumprod(kernel, window))
    except TypeError as e:
        raise ValueError("signal must be an iterable of numeric values") from e

    return result

