def random_derangement(iterable: Iterable[Any]) -> list[Any]:
    """Return a random derangement of elements in the iterable.

    A derangement is a permutation with no fixed points (i.e., no element appears in its original position).

    Parameters:
    iterable (Iterable[Any]): An iterable of elements to be deranged.

    Example:
    random_derangement([1, 2, 3]) -> [2, 3, 1] (example output, actual result may vary)

    """
    try:
        seq = tuple(iterable)
    except TypeError as e:
        raise ValueError("Input must be an iterable.") from e

    if len(seq) < 2:
        if len(seq) == 0:
            return []
        raise ValueError("No derangements possible for a single-element iterable.")

    perm = list(range(len(seq)))
    start = tuple(perm)
    while True:
        shuffle(perm)
        if not any(map(is_, start, perm)):
            return list(itemgetter(*perm)(seq))

